import React from "react";
import { loadFont } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  AbsoluteFill,
  Img,
  OffthreadVideo,
  Sequence,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import ED from "./edicao.json";

// v6 (10/11): tirado o trecho antigo que aparecia logo depois do "mais distante".
// v5 (10/11): vídeos novos do o diretor: novo-1 no "família distante"; novo-2 + novo-3 no "queremos receber vocês".
// v4 (09/11): cenas e layout da v1 ("FAMÍLIAS") + abertura da v3 (gancho na placa); sem música.
// v3 (09/11): gancho começa direto na fala (sem a abertura parada de 0,95 s da referência); tempos −0,95 s.
// v2 (09/11): ordem das cenas do vídeo de referência do o diretor, gancho "Se você mora no Park Way…" recortado dele.
// QUINTA · Quintal Real Amor (pastor Bruno). Formato "notícia da região" pedido pelo o diretor (print de referência em
// (arquivo do cliente)): faixa vermelha no topo, bloco branco com ATENÇÃO + título + linha fina,
// o vídeo dele no meio como player, e a pergunta + botão de WhatsApp embaixo. Sem a marca do g1/Globo: no lugar,
// o logo da igreja. A fala do pastor é a narração (5 tomadas, só aparadas). O enquadramento segue o rosto dele
// (edicao.json, gerado por (arquivo do cliente)) para a cabeça nunca sair do player.

const { fontFamily: MS } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: IN } = loadInter("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const QT_FPS = 30;
export const QT_FRAMES = Math.round(ED.dur * QT_FPS);

const RED = "#C8141E";
const RED_D = "#8E0A10";
const INK = "#111111";
const PAPER = "#F3F3F3";
const YEL = "#FFD21F";

const TITULO = "FAMÍLIAS";
const WIN_TOP = 566;
const WIN_H = 920;
const BOT_TOP = WIN_TOP + WIN_H;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// B-roll dos eventos, por cima do pastor, no tempo da composição. top = recorte vertical (px na largura 1080).
type BR = { a: number; b: number; src: string; from: number; top: number; h: number; s?: number; left?: number; rate?: number };
// v2: mesma ordem de cenas do vídeo que o o diretor mandou (src/ref-ordem.mp4), com os tempos levados para esta fala.
const BROLL: BR[] = [
  { a: 3.62, b: 5.87, src: "novo-1", from: 0.0, top: 0, h: 920, rate: 0.8 }, // v6: entra 0,16 s antes (a fusão não mostra o trecho antigo) e cobre até 5,87 s (o gancho traz um trecho antigo queimado); 1,8 s do novo-1 a 0,86x
  { a: 23.13, b: 25.58, src: "evento-1", from: 3.0, top: 400, h: 1920 },
  { a: 31.18, b: 33.33, src: "evento-5", from: 2.0, top: 600, h: 1728 },
  { a: 33.33, b: 35.68, src: "evento-4", from: 10.0, top: 40, h: 1800 },
  { a: 37.56, b: 39.8, src: "novo-2", from: 0.0, top: 0, h: 920 }, // v5: "queremos receber vocês como estão"
  { a: 39.8, b: 43.98, src: "novo-3", from: 0.0, top: 0, h: 920 }, // v5: "caminhar juntos… fortalecer a fé"
  { a: 56.78, b: 58.73, src: "evento-6", from: 6.0, top: 90, h: 1728 },
  { a: 58.73, b: 61.18, src: "evento-1", from: 14.0, top: 400, h: 1920 },
];

const HOOK = ED.hook;
const CTA1 = 53.88; // "clique em Saiba Mais"
const TAPS = [54.58, 62.18];
const PERGUNTAS: [number, string][] = [
  [0, "VOCÊ MORA NO PARK WAY OU EM ÁGUAS CLARAS?"],
  [HOOK, "SENTE QUE SUA FAMÍLIA PRECISA DE UM NOVO COMEÇO?"],
  [CTA1, "CLIQUE EM SAIBA MAIS E FALE COM A NOSSA EQUIPE"],
];

const useT = () => useCurrentFrame() / QT_FPS;
const sp = (t: number, at: number, damping = 18, stiffness = 140) =>
  spring({ fps: QT_FPS, frame: Math.max(0, (t - at) * QT_FPS), config: { damping, stiffness, overshootClamping: false } });

// ---------- texto que sobe da linha ----------
const Rise: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ t, at, children, style }) => {
  const p = spring({ fps: QT_FPS, frame: Math.max(0, (t - at) * QT_FPS), config: { damping: 200 } });
  return (
    <div style={{ overflow: "hidden", ...style }}>
      <div style={{ transform: `translateY(${(1 - p) * 105}%)` }}>{children}</div>
    </div>
  );
};

// ---------- o pastor, enquadrado pelo rosto ----------
const lerpArr = (ts: number[], vs: number[], t: number) => interpolate(t, ts, vs, cl);

const Pastor: React.FC<{ take: number; src: number; dur: number }> = ({ take, src }) => {
  const f = useCurrentFrame();
  if (take === 0) {
    return (
      <AbsoluteFill style={{ overflow: "hidden" }}>
        <OffthreadVideo src={staticFile("quinta/gancho.mp4")} muted style={{ position: "absolute", width: 1080, height: WIN_H, left: 0, top: 0 }} />
      </AbsoluteFill>
    );
  }
  const st = src + f / QT_FPS;
  const c = (ED.crop as Record<string, { t: number[]; s: number[]; x: number[]; y: number[] }>)[String(take)];
  const s = lerpArr(c.t, c.s, st);
  const x = lerpArr(c.t, c.x, st);
  const y = lerpArr(c.t, c.y, st);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <OffthreadVideo
        src={staticFile(`quinta/fala-${take}.mp4`)}
        startFrom={Math.round(src * QT_FPS)}
        muted
        style={{ position: "absolute", width: 1080 * s, height: 1920 * s, left: -x * s, top: -y * s, maxWidth: "none" }}
      />
    </AbsoluteFill>
  );
};

const Broll: React.FC<{ b: BR }> = ({ b }) => {
  const f = useCurrentFrame();
  const d = (b.b - b.a) * QT_FPS;
  const z = interpolate(f, [0, d], [1.0, 1.06], cl);
  const inn = interpolate(f, [0, 5], [0, 1], cl);
  return (
    <AbsoluteFill style={{ overflow: "hidden", opacity: inn }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: WIN_H, transform: `scale(${z})`, transformOrigin: "50% 35%" }}>
        <OffthreadVideo
          src={staticFile(`quinta/${b.src}.mp4`)}
          startFrom={Math.round(b.from * QT_FPS)}
          playbackRate={b.rate ?? 1}
          muted
          style={{ position: "absolute", width: 1080 * (b.s ?? 1), height: b.h * (b.s ?? 1), left: -(b.left ?? 0), top: -b.top, maxWidth: "none" }}
        />
      </div>
    </AbsoluteFill>
  );
};

// ---------- legenda ----------
const Caption: React.FC<{ t: number }> = ({ t }) => {
  const c = ED.caps.find((k) => t >= k.t - 0.02 && t < k.e);
  if (!c) return null;
  const p = sp(t, c.t - 0.02, 16, 220);
  return (
    <div
      style={{
        position: "absolute",
        left: 120,
        right: 120,
        top: WIN_TOP + 700,
        textAlign: "center",
        fontFamily: MS,
        fontWeight: 900,
        fontSize: 64,
        lineHeight: 1.05,
        textTransform: "uppercase",
        color: "#fff",
        textShadow: "0 3px 0 rgba(0,0,0,0.55), 0 0 18px rgba(0,0,0,0.6)",
        transform: `scale(${0.86 + 0.14 * p})`,
        opacity: Math.min(1, p * 2),
      }}
    >
      {c.words.map((w, i) => (
        <span key={i} style={{ color: t >= w.t ? (i === c.words.length - 1 || t < c.words[i + 1].t ? YEL : "#fff") : "#fff" }}>
          {w.w.replace(/[.,]$/, "")}
          {i < c.words.length - 1 ? " " : ""}
        </span>
      ))}
    </div>
  );
};

// ---------- player (barra de baixo) ----------
const mmss = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
const PlayerBar: React.FC<{ t: number }> = ({ t }) => {
  const prog = Math.min(1, t / ED.dur);
  const y = WIN_TOP + WIN_H - 78;
  return (
    <>
      <div style={{ position: "absolute", left: 0, right: 0, top: WIN_TOP + WIN_H - 330, height: 330, background: "linear-gradient(to bottom, rgba(0,0,0,0), rgba(0,0,0,0.62))" }} />
      <svg style={{ position: "absolute", left: 40, top: y + 8 }} width="36" height="40" viewBox="0 0 36 40">
        <rect x="4" y="4" width="9" height="32" rx="2" fill="#fff" />
        <rect x="21" y="4" width="9" height="32" rx="2" fill="#fff" />
      </svg>
      <div style={{ position: "absolute", left: 100, top: y + 6, fontFamily: IN, fontWeight: 500, fontSize: 32, color: "#fff", fontVariantNumeric: "tabular-nums" }}>
        {mmss(t)} / {mmss(ED.dur)}
      </div>
      <div style={{ position: "absolute", left: 330, width: 540, top: y + 26, height: 5, borderRadius: 3, background: "rgba(255,255,255,0.35)" }}>
        <div style={{ width: `${prog * 100}%`, height: "100%", borderRadius: 3, background: "#fff" }} />
        <div style={{ position: "absolute", left: `calc(${prog * 100}% - 9px)`, top: -7, width: 18, height: 18, borderRadius: 9, background: "#fff" }} />
      </div>
      <svg style={{ position: "absolute", left: 912, top: y + 6 }} width="48" height="44" viewBox="0 0 48 44">
        <path d="M4 15h9l12-10v34L13 29H4z" fill="#fff" />
        <path d="M31 13c4 4 4 14 0 18M36 8c7 7 7 21 0 28" stroke="#fff" strokeWidth="3.5" fill="none" strokeLinecap="round" />
      </svg>
      <svg style={{ position: "absolute", left: 990, top: y + 8 }} width="40" height="40" viewBox="0 0 40 40">
        <path d="M3 14V3h11M26 3h11v11M37 26v11H26M14 37H3V26" stroke="#fff" strokeWidth="4.5" fill="none" />
      </svg>
    </>
  );
};

const WhatsIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 64 64">
    <path d="M32 4C16.5 4 4 16.3 4 31.6c0 5.4 1.6 10.5 4.4 14.8L5 60l14-3.6c4 2.2 8.5 3.4 13 3.4 15.5 0 28-12.3 28-27.6S47.5 4 32 4z" fill="#25D366" />
    <path d="M32 9c12.7 0 23 10.1 23 22.6S44.7 54.2 32 54.2c-4.1 0-8.1-1.1-11.6-3.1l-.8-.5-8.1 2.1 2.1-7.9-.5-.8C10.9 40.4 9 36.1 9 31.6 9 19.1 19.3 9 32 9z" fill="#fff" />
    <path d="M24 19c-.6-1.4-1.3-1.4-1.9-1.4h-1.6c-.6 0-1.5.2-2.2 1-.8.8-2.9 2.8-2.9 6.8s3 7.9 3.4 8.4c.4.5 5.8 9.1 14.3 12.4 7.1 2.8 8.5 2.2 10.1 2.1 1.5-.1 5-2 5.7-4 .7-2 .7-3.7.5-4-.2-.4-.8-.6-1.6-1s-5-2.4-5.7-2.7c-.8-.3-1.3-.4-1.9.4-.6.8-2.2 2.7-2.6 3.2-.5.6-1 .6-1.8.2-.8-.4-3.5-1.3-6.7-4.1-2.5-2.2-4.1-4.9-4.6-5.7-.5-.8 0-1.3.4-1.7.4-.4.8-1 1.2-1.4.4-.5.5-.8.8-1.4.3-.6.1-1-.1-1.4-.2-.4-1.7-4.3-2.4-5.7z" fill="#25D366" />
  </svg>
);

const Cursor: React.FC<{ t: number }> = ({ t }) => {
  const tap = TAPS.find((a) => t > a - 0.75 && t < a + 0.55);
  if (tap === undefined) return null;
  const inn = sp(t, tap - 0.75, 20, 120);
  const out = interpolate(t, [tap + 0.35, tap + 0.55], [1, 0], cl);
  const press = interpolate(t, [tap - 0.05, tap, tap + 0.12], [1, 0.86, 1], cl);
  const x = interpolate(inn, [0, 1], [880, 760]);
  const y = interpolate(inn, [0, 1], [1930, 1828]);
  const ring = interpolate(t, [tap, tap + 0.4], [0, 1], cl);
  return (
    <>
      {t >= tap && (
        <div style={{ position: "absolute", left: x - 10 - 60 * ring, top: y - 10 - 60 * ring, width: 20 + 120 * ring, height: 20 + 120 * ring, borderRadius: "50%", border: "4px solid rgba(255,255,255,0.8)", opacity: 1 - ring }} />
      )}
      <svg style={{ position: "absolute", left: x - 14, top: y - 6, transform: `scale(${press})`, transformOrigin: "14px 6px", opacity: out, filter: "drop-shadow(0 6px 10px rgba(0,0,0,0.35))" }} width="86" height="96" viewBox="0 0 43 48">
        <path d="M14 3c2 0 3.5 1.5 3.5 3.5V22l2-.6c1.8-.5 3.6.4 4.2 2.1l.1.3 1.8-.4c1.8-.4 3.5.6 4 2.3l1.6-.2c1.9-.2 3.5 1.1 3.8 3l.9 7.3c.6 4.8-1.5 9.5-5.5 12.1l-1 .6H17.6l-9.5-12.6c-1.2-1.6-.9-3.9.7-5.1 1.5-1.1 3.6-1 4.9.4l-.2-25.5C13.5 4.6 12 3 14 3z" fill="#fff" stroke="#111" strokeWidth="2" strokeLinejoin="round" />
      </svg>
    </>
  );
};

export const Quinta: React.FC = () => {
  const t = useT();
  const { fps } = useVideoConfig();
  const head = sp(t, 0, 22, 160);
  const tag = sp(t, 0.12, 14, 180);
  const bot = sp(t, 0.18, 22, 150);
  const btn = sp(t, 0.42, 14, 160);
  const play = interpolate(t, [0.2, 0.35], [1, 0], cl);
  const playPress = interpolate(t, [0.05, 0.12, 0.22], [1, 0.85, 1.1], cl);

  const pulse = TAPS.reduce((acc, a) => acc + interpolate(t, [a - 0.05, a, a + 0.12, a + 0.4], [0, -0.05, 0.04, 0], cl), 0);

  return (
    <AbsoluteFill style={{ background: PAPER }}>
      {/* ---------- player com o pastor e os eventos ---------- */}
      <div style={{ position: "absolute", left: 0, top: WIN_TOP, width: 1080, height: WIN_H, overflow: "hidden", background: "#000" }}>
        {ED.pieces.map((p, i) => (
          <Sequence key={i} from={Math.round(p.from * fps)} durationInFrames={Math.round((i === ED.pieces.length - 1 ? ED.dur - p.from : p.dur) * fps) + 1}>
            <Pastor take={p.take} src={p.src} dur={p.dur} />
          </Sequence>
        ))}
        {BROLL.map((b, i) => (
          <Sequence key={`b${i}`} from={Math.round(b.a * fps)} durationInFrames={Math.round((b.b - b.a) * fps)}>
            <Broll b={b} />
          </Sequence>
        ))}
      </div>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920 }}>
        <PlayerBar t={t} />
        <Caption t={t} />
        {play > 0 && (
          <div style={{ position: "absolute", left: 540 - 85, top: WIN_TOP + WIN_H / 2 - 85, width: 170, height: 170, borderRadius: "50%", border: "6px solid #fff", background: "rgba(0,0,0,0.25)", opacity: play, transform: `scale(${playPress})`, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <svg width="70" height="70" viewBox="0 0 70 70"><path d="M22 12l38 23-38 23z" fill="#fff" /></svg>
          </div>
        )}
      </div>

      {/* ---------- topo vermelho ---------- */}
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 146, background: `linear-gradient(90deg, ${RED_D}, ${RED} 55%, ${RED_D})`, transform: `translateY(${(head - 1) * 146}px)`, display: "flex", alignItems: "center", paddingLeft: 60 }}>
        <Img src={staticFile("quinta/logo-branco.png")} style={{ height: 96 }} />
        <div style={{ width: 3, height: 84, background: "rgba(255,255,255,0.85)", margin: "0 40px" }} />
        <div style={{ fontFamily: MS, fontWeight: 700, fontSize: 46, color: "#fff", letterSpacing: 0.5 }}>NOTÍCIAS DA REGIÃO</div>
      </div>

      {/* ---------- bloco branco ---------- */}
      <div style={{ position: "absolute", left: 60, top: 172, height: 92, padding: "0 34px", borderRadius: 14, background: `linear-gradient(180deg, ${RED}, #A80F17)`, display: "flex", alignItems: "center", transform: `scale(${tag})`, transformOrigin: "0% 50%", boxShadow: "0 6px 14px rgba(160,10,20,0.25)" }}>
        <span style={{ fontFamily: MS, fontWeight: 800, fontSize: 60, color: "#fff", letterSpacing: 1 }}>ATENÇÃO</span>
      </div>
      <Rise t={t} at={0.2} style={{ position: "absolute", left: 50, top: 268 }}>
        <div style={{ fontFamily: MS, fontWeight: 900, fontSize: 160, lineHeight: 0.9, color: INK, letterSpacing: -2 }}>{TITULO}</div>
      </Rise>
      <div style={{ position: "absolute", left: 62, top: 438, width: 7, height: 112, background: RED, transform: `scaleY(${sp(t, 0.32, 200, 120)})`, transformOrigin: "50% 0%" }} />
      <Rise t={t} at={0.36} style={{ position: "absolute", left: 96, top: 434, width: 940 }}>
        <div style={{ fontFamily: IN, fontWeight: 500, fontSize: 47, lineHeight: 1.25, color: "#2A2A2A" }}>Igreja abre as portas para receber</div>
      </Rise>
      <Rise t={t} at={0.42} style={{ position: "absolute", left: 96, top: 492, width: 940 }}>
        <div style={{ fontFamily: IN, fontWeight: 500, fontSize: 47, lineHeight: 1.25, color: "#2A2A2A" }}>e caminhar junto com a sua família.</div>
      </Rise>

      {/* ---------- base vermelha ---------- */}
      <div style={{ position: "absolute", left: 0, top: BOT_TOP, width: 1080, height: 1920 - BOT_TOP, overflow: "hidden", background: `linear-gradient(160deg, #E0242C, ${RED} 45%, ${RED_D})`, transform: `translateY(${(1 - bot) * 440}px)` }}>
        <svg style={{ position: "absolute", left: 0, top: 0 }} width="1080" height="434" viewBox="0 0 1080 434">
          <path d="M-40 300 C 260 180, 560 420, 1120 220 L1120 434 L-40 434 Z" fill="rgba(0,0,0,0.12)" />
          <path d="M-40 360 C 300 260, 640 460, 1120 300 L1120 434 L-40 434 Z" fill="rgba(0,0,0,0.10)" />
        </svg>
        <div style={{ position: "absolute", left: 90, right: 90, top: 34, height: 220, display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", fontFamily: MS, fontWeight: 800, fontSize: 58, lineHeight: 1.12, color: "#fff", textShadow: "0 3px 8px rgba(0,0,0,0.2)", textWrap: "balance" } as React.CSSProperties}>
          {PERGUNTAS.map(([at, txt], i) => {
            const next = i + 1 < PERGUNTAS.length ? PERGUNTAS[i + 1][0] : 999;
            if (t < at || t >= next) return null;
            const p = i === 0 ? 1 : sp(t, at + 0.05, 200, 100);
            const out = interpolate(t, [next - 0.15, next], [1, 0], cl);
            return (
              <div key={i} style={{ position: "absolute", overflow: "hidden", opacity: out }}>
                <div style={{ transform: `translateY(${(1 - p) * 105}%)` }}>{txt}</div>
              </div>
            );
          })}
        </div>
      </div>
      <div style={{ position: "absolute", left: 90, width: 900, top: 1756, height: 120, borderRadius: 60, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", gap: 26, boxShadow: "0 10px 24px rgba(0,0,0,0.22)", transform: `scale(${btn * (1 + pulse)})`, opacity: Math.min(1, btn * 1.5) }}>
        <WhatsIcon size={78} />
        <span style={{ fontFamily: MS, fontWeight: 800, fontSize: 50, color: INK, letterSpacing: 0.2 }}>CONHEÇA NOSSA IGREJA</span>
        <svg width="30" height="40" viewBox="0 0 30 40"><path d="M8 6l14 14-14 14" stroke={INK} strokeWidth="5" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
      </div>
      <Cursor t={t} />
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { Quinta, QT_FPS, QT_FRAMES } from "./Quinta";

const Root: React.FC = () => (
  <>
    <Composition id="Quinta" component={Quinta} durationInFrames={QT_FRAMES} fps={QT_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
